def main():
    subject, students, marks = initialize_data()
    while(1):
        print('-'* 75)
        choice = int(input('1. Press 1 to Display Student Results\n2. Press 2 to Add a new Student Record\n3. Press 3 to Display Analyzed Results\n4. Press 4 to Exit\n'))
        print('-'* 75)
        if(choice == 1):
            display_record(students, subject, marks)
        elif(choice == 2):
            students,marks = add_record(students, subject, marks)
        elif(choice == 3):
            obtain_results(students, subject, marks)
        elif(choice == 4):
            break;
        else:
            print('Invalid Choice')
